        final stream = FakeStreamFunction([
          truncatedToolCallTurn,
          emptyTurn(),
          emptyTurn(),
          emptyTurn(),
          emptyTurn(),
          textTurn('never reached'),
        ]);
        final cli = cliFor(stream);

        final exitCode = await cli.runHeadless('do the task');

