    QueueMode followUpMode = QueueMode.oneAtATime,
    this.toolExecution = ToolExecutionMode.parallel,
    this.maxEmptyRetries = 1,
    this.runIdleTimeout = defaultRunIdleTimeout,
    this.onRunIdleTimeout,
