          config: cliShapeConfig(),
          streamFunction: fake.call,
          toolExecutor: (_, _, _) async => ToolExecutionResult.text('done'),
        );

        final events = await stream.toList();
        // partial + 1 original empty + exactly 3 retries = 5 requests.
        expect(fake.calls, 5);
