    Model? model,
    String? systemPrompt,
    List<Tool>? tools,
    List<Message>? messages,
    required this.streamFunction,
    ToolExecutor? toolExecutor,
    ToolRegistry? toolRegistry,
    this.beforeToolCall,
    this.afterToolCall,
    this.transformContext,
    this.budgetLineProvider,
