/// The E2/E5 race, scripted: the final hiccup retry is in flight when the
/// abort lands — the stream only completes AFTER the cancel, and the
/// provider's answer is a length-flagged empty.
class _CancelDuringFinalRetryStreamFunction {
  _CancelDuringFinalRetryStreamFunction(this.turns);

  final List<List<AssistantMessageEvent>> turns;
  final calls = <Context>[];

  AssistantMessageEventStream call(
    Model model,
    Context context, {
    CancelToken? cancelToken,
  }) {
    calls.add(context);
    final stream = AssistantMessageEventStream();
    final isLast = calls.length == turns.length;
    for (final event in turns.removeAt(0)) {
      stream.push(event);
    }
    if (isLast && cancelToken != null) {
      // Hold the stream open until the abort lands: the empty completion
      // and the cancel arrive together.
      cancelToken.onCancel.then((_) => stream.end());
    } else {
      stream.end();
    }
    return stream;
  }
