class _CancelAfterEmptyStreamFunction {
  _CancelAfterEmptyStreamFunction(this.turns, this.source)
    : cancelOnTurn = turns.length - 1;

  final List<List<AssistantMessageEvent>> turns;
  final CancelTokenSource source;
