AssistantMessage _assistant({
  List<ContentBlock> content = const [],
  StopReason stopReason = StopReason.stop,
  String? errorMessage,
}) => AssistantMessage(
  content: content, api: _model.api, provider: _model.provider, model: _model.id,
  usage: Usage.zero, stopReason: stopReason, errorMessage: errorMessage,
  timestamp: DateTime.now(),
);

ToolCall _call(String id, String name, [Map<String, dynamic>? args]) =>
    ToolCall(id: id, name: name, arguments: args ?? {});

List<AssistantMessageEvent> _toolTurn(List<ToolCall> calls, {StopReason reason = StopReason.toolUse}) {
  final empty = _assistant();
  final partial = _assistant(content: calls, stopReason: reason);
  final events = <AssistantMessageEvent>[StartEvent(partial: empty)];
  for (var i = 0; i < calls.length; i++) {
    events
      ..add(ToolCallStartEvent(contentIndex: i, partial: empty))
      ..add(ToolCallEndEvent(contentIndex: i, toolCall: calls[i], partial: partial));
  }
  events.add(DoneEvent(reason: reason, message: partial));
  return events;
}

