    final index = contexts.length;
    contexts.add(Context(systemPrompt: context.systemPrompt, messages: List.of(context.messages), tools: context.tools));
    final stream = AssistantMessageEventStream();
    for (final event in turns.removeAt(0)) { stream.push(event); }
    stream.end();
    if (index == cancelOnTurn) source.cancel('test abort');
    return stream;
  }
}

