  _state._streamingMessage = null;
  _state._errorMessage = null;
  _armRunWatchdog();

  try {
    await executor(run.source.token);
  } catch (error) {
    await _handleRunFailure(error, run.source.token.isCancelled);
  } finally {
    await _settleRun();
  }
}

